window.addEventListener('message',event=>{if(event.origin===location.origin&&[N('shell-feed').contentWindow,N('library-feed')?.contentWindow].includes(event.source)&&event.data?.type==='relaxe-shell-destination'&&destinations.some(d=>d[0]===event.data.destination)){if(event.data.destination==='search')openSearch();else showDestination(event.data.destination)}});

// Synthetic, account-partitioned search context shared by these HTML studies only.
